/*
 * A275598  Primes p such that the number of odd divisors of p-1 is a prime q
 *          which is equal to the number of odd divisors of p+1.
 * https://oeis.org/A275598
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   A275598 – primes p such that the number of odd divisors of p-1
 *            equals the number of odd divisors of p+1, and this number itself
 *            is a prime. The sequence is generated by searching primes in
 *            increasing order until the n‑th term is found
 * Range:     u8 n <= 5, u16 n <= 7, u32 n <= 7, u64 n <= 7, u128 n <= 7,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* Static storage for the sequence values. */
static seq_t   *seq_vals  = NULL;
static size_t  seq_len   = 0;   /* number of terms currently stored */
static size_t  seq_cap   = 0;   /* capacity of seq_vals */

/* Last prime that has been examined.  Start after 2. */
static uint64_t last_prime = 2;

/* ------------------------------------------------------------------ */
/* Helper: simple primality test for a 64‑bit integer.                */
/* ------------------------------------------------------------------ */
static bool is_prime_small(uint64_t x)
{
    if (x < 2) return false;
    if (x % 2 == 0) return x == 2;
    for (uint64_t d = 3; d <= x / d; d += 2)
        if (x % d == 0) return false;
    return true;
}

/* ------------------------------------------------------------------ */
/* Helper: count odd divisors of n.  The odd part of n is obtained by
   removing all factors of 2.  Then a standard prime‑factorisation is
   performed.                                                        */
/* ------------------------------------------------------------------ */
static uint64_t odd_divisor_count(uint64_t n)
{
    /* remove all factors of 2 */
    while ((n & 1ULL) == 0) n >>= 1;
    uint64_t cnt = 1;
    for (uint64_t d = 3; d <= n / d; d += 2) {
        if (n % d == 0) {
            uint64_t exp = 0;
            while (n % d == 0) {
                n /= d;
                ++exp;
            }
            cnt *= (exp + 1);
        }
    }
    if (n > 1) /* remaining prime factor */
        cnt *= 2;
    return cnt;
}

/* ------------------------------------------------------------------ */
/* Replace the generic realloc cast with explicit type to satisfy
   both C and C++ mode.                                                */
/* ------------------------------------------------------------------ */
static void ensure_seq_capacity(size_t needed)
{
    if (needed <= seq_cap) return;
    size_t new_cap = seq_cap ? seq_cap * 2 : 16;
    while (new_cap < needed) new_cap *= 2;
    seq_vals = (seq_t *)realloc(seq_vals, new_cap * sizeof(seq_t));
    seq_cap = new_cap;
}

/* ------------------------------------------------------------------ */
/* Main sequence function.                                            */
/* ------------------------------------------------------------------ */
seq_t a(idx_t n)
{
    /* Convert n once to avoid repeated casting in loops. */
    size_t target = (size_t)n;

    /* Grow the sequence until we have at least n terms. */
    while (seq_len < target) {
        /* Find the next prime greater than last_prime.  Using a simple
           incrementing loop with trial division is sufficient for the
           small number of terms expected here. */
        uint64_t cand = last_prime + 1;
        while (!is_prime_small(cand)) ++cand;
        last_prime = cand;

        /* Evaluate the property for this prime. */
        uint64_t q1 = odd_divisor_count(cand - 1);
        uint64_t q2 = odd_divisor_count(cand + 1);

        if (q1 == q2 && is_prime_small(q1)) {
            ensure_seq_capacity(seq_len + 1);
            seq_vals[seq_len++] = (seq_t)cand;
        }
    }

    return seq_vals[target - 1];
}
